'use strict';
Adventures.install();
const AdventureUI=(()=>{
 const num=n=>n.toLocaleString('th-TH',{maximumFractionDigits:0});
 function refresh(message){save();clock.reset();render();open();if(message)toast(message)}
 function panel(s){const a=Adventures.ensure(s),active=a.active,m=active&&Adventures.get(active.id);return `<section class="panel adventure-overview"><div><span class="eyebrow">สมาคมนักผจญภัย · หลายเผ่าร่วมคณะ</span><h3>${a.member?'แรงค์ '+Adventures.ranks[a.rank]+' · '+num(a.xp)+' ประสบการณ์':'ทางที่ต้องเลือกด้วยตนเอง'}</h3><p>${m?esc(m.name)+' · '+['กำลังเข้าถึงเขตงาน','พบสิ่งเฝ้าทาง','เตรียมกลับและแบ่งส่วน'][active.stage]:a.member?'เสบียงและการพักฟื้นสำคัญพอ ๆ กับค่าจ้าง':'สำรวจดันเจี้ยน ป่าลึก ทางน้ำ และรอยแยกตามรูปกาย'}</p></div><button class="secondary" id="openAdventures">${m?'ดูงานที่รับไว้':'ดูทะเบียนและงาน'} →</button></section>`}
 function open(){const s=state,a=Adventures.ensure(s),native=RaceDrives.cashless(s),active=a.active,m=active&&Adventures.get(active.id),locked=Adventures.locked(s);modal(`<section class="adventure-dialog"><span class="eyebrow">ปี ${WorldTimeline.year(s)} · ${esc(RACES[s.race][0])}</span><h2>สมาคมนักผจญภัย</h2><p>${esc(Adventures.role(s))}</p><div class="adventure-rank"><b>${Adventures.ranks[a.rank]}</b><div><strong>${num(a.xp)} ประสบการณ์</strong><progress max="${Adventures.thresholds[Math.min(7,a.rank+1)]||1}" value="${Math.min(a.xp,Adventures.thresholds[Math.min(7,a.rank+1)])}" aria-label="ประสบการณ์นักผจญภัย"></progress><small>สำเร็จ ${a.completed} งาน · ถอนตัว ${a.failed} งาน</small></div></div><p class="adventure-note">แรงค์สมาคมแยกจาก Tier เผ่าและชนชั้น งานที่รับผิดชอบสูงต้องมีทั้งประสบการณ์และรายงานสำเร็จ ไม่มีเงินเดือนจากการถือทะเบียน ค่าสมาชิก ${native?'แหล่งถิ่น 2':'120 ทอง'} ต่อปี</p>${!a.member?`<button class="primary" id="joinAdventures" ${locked?'disabled':''}>ลงทะเบียนแรงค์ F · ไม่มีค่าเข้า</button>${Engine.biological(s)<16?'<p class="adventure-note">เริ่มร่วมคณะได้เมื่อถึงวัยฝึกงานของเผ่า</p>':''}`:''}${a.member&&m?`<section class="adventure-active"><span class="eyebrow">งานที่รับไว้ · ช่วง ${active.stage+1}/3</span><h3>${esc(m.name)}</h3><p>${esc(m.brief)}</p><p class="adventure-note">ออกเดินทางแล้ว · ระบบจะเล่าเหตุเมื่อถึงช่วงสำรวจ คุณพักหรือถอนตัวได้ ค่าของที่ใช้แล้วไม่คืน</p><button class="secondary" id="withdrawAdventure" ${locked?'disabled':''}>ถอนตัวและส่งรายงานกลับ</button></section>`:''}${a.member&&!m?`<h3>งานที่มีคณะรับร่วมในช่วงนี้</h3><div class="adventure-board">${Adventures.board(s).map(m=>{const why=Adventures.reason(s,m),risk=Math.round(Adventures.chance(s,m)*100);return `<article><span class="eyebrow">งานแรงค์ ${Adventures.ranks[m.rank]}</span><h3>${esc(m.name)}</h3><p>${esc(m.brief)}</p><dl><div><dt>ส่วนแบ่งเมื่อสำเร็จ</dt><dd>${native?'แหล่งถิ่น +12':num(m.reward)+' ทองก่อนภาษี 18%'}</dd></div><div><dt>เตรียมเสบียง</dt><dd>${native?'แหล่งถิ่น −'+(6+m.rank*2):num(m.cost)+' ทอง'}</dd></div></dl><small class="adventure-risk">โอกาสเสียเปรียบโดยประมาณ ${risk}% · บาดเจ็บ คำสาป หรือเสียชีวิตต่อเนื่องเป็นไปได้</small>${why?`<p class="adventure-note">${esc(why)}</p>`:''}<div class="adventure-actions"><button class="secondary" data-contract="${m.id}" ${why||native&&s.raceDrives.resource<6+m.rank*2||!native&&s.gold<m.cost?'disabled':''}>เตรียมเองและรับงาน</button>${!native?`<button class="secondary" data-contract-advance="${m.id}" ${why?'disabled':''}>รับเสบียงล่วงหน้า · คืน ${num(Math.round(m.cost*1.15))} ทอง</button>`:''}</div></article>`}).join('')}</div><p class="adventure-note">การสำรวจหนึ่งช่วงใช้เวลาประมาณสามเดือนและมีหลายการตัดสินใจในช่วงนั้น หลังกลับต้องพักอย่างน้อยหนึ่งช่วง รายได้งานนอกเวลาต้องหักเวลาที่ออกสำรวจ</p>`:''}${a.member?`${!native?'<button class="secondary" id="guildBudget">บัญชีรายปีและแผนที่พักรวมสมาคม →</button>':''}<h3>เครื่องช่วยและสิ่งคุ้มร่าง</h3><p>สภาพ ${Math.round(a.gear.condition)}/100 · รูปแบบเข้ากับร่างของ${esc(RACES[s.race][0])}</p><div class="adventure-gear">${[['weapon','การรับมือสิ่งขวางทาง'],['ward','สิ่งคุ้มร่างและจุดยึด'],['kit','เครื่องช่วยสำรวจ']].map(([id,name])=>`<button class="secondary" data-adventure-gear="${id}" ${locked||!!m||a.gear[id]>=3?'disabled':''}><b>${name} ${a.gear[id]}/3</b><small>${native?'แหล่งถิ่น '+(12+a.gear[id]*8):num([450,1800,6500][a.gear[id]]||0)+' ทอง'} · ใช้หนึ่งช่วงเตรียมตัว</small></button>`).join('')}<button class="secondary" data-adventure-gear="repair" ${locked||!!m||a.gear.condition>=100?'disabled':''}>ซ่อมและตรวจสภาพ · ${native?'แหล่งถิ่น 8':num(Math.round(180+(100-a.gear.condition)*8))+' ทอง'}</button></div>`:''}${a.history.length?`<details><summary>งานที่เคยกลับมาเล่า</summary>${a.history.map(h=>`<p><small>ปี ${h.year} · อายุ ${h.age}</small><br>${esc(h.text)}</p>`).join('')}</details>`:''}<p id="adventureError" class="adventure-risk" role="status"></p></section>`);if($('#guildBudget'))$('#guildBudget').onclick=EpochUI.money;if($('#joinAdventures'))$('#joinAdventures').onclick=()=>{if(Adventures.join(s))refresh('ชื่อของคุณอยู่ในทะเบียนแล้ว')};for(const [sel,advance] of [['[data-contract]',false],['[data-contract-advance]',true]])document.querySelectorAll(sel).forEach(b=>b.onclick=()=>{if(Adventures.accept(s,advance?b.dataset.contractAdvance:b.dataset.contract,advance))refresh('เตรียมคณะไว้แล้ว ชีวิตจะเล่าการเดินทางเมื่อเวลาเดินต่อ');else $('#adventureError').textContent='ตรวจเสบียง สิทธิ และเรื่องที่ยังค้างอยู่ก่อน'});document.querySelectorAll('[data-adventure-gear]').forEach(b=>b.onclick=()=>{if(Adventures.train(s,b.dataset.adventureGear))refresh('บันทึกการเตรียมตัวแล้ว');else $('#adventureError').textContent='ทุนหรือแหล่งถิ่นไม่พอ หรือเตรียมตัวในช่วงนี้แล้ว'});if($('#withdrawAdventure'))$('#withdrawAdventure').onclick=()=>{if(Adventures.withdraw(s))refresh('ส่งรายงานถอนตัวแล้ว')};}
 function bind(){if($('#openAdventures'))$('#openAdventures').onclick=open}
 return {panel,open,bind};
})();
